"""TensorRT runtime pack for the E4-ALL fast kernel (generated by trt_pack/make.py). Kaggle T4, internet on:
pip-installs tensorrt-cu12 + tensorrt-lean-cu12 11.4.0.106, builds the E4-ALL slim r50 engine twice on this T4 (full plan;
version-compatible plan for the lean runtime), and writes /kaggle/working/trtpack: full/ (tensorrt + bindings + libnvinfer
only, no builder resources), lean/ (tensorrt_lean + bindings + libnvinfer_lean), both engines, manifest.json. Attached as a
kernel source to the offline fast kernel (internet off)."""
import glob, hashlib, json, os, shutil, subprocess, sys, time
P = "/kaggle/working/trtpack"; os.makedirs(P, exist_ok=True); M = {}
t = time.perf_counter()
p = subprocess.run([sys.executable, "-m", "pip", "install", "-q", "tensorrt-cu12==11.4.0.106", "tensorrt-lean-cu12==11.4.0.106"],
                   capture_output=True, text=True)
M["pip_s"] = round(time.perf_counter() - t, 1); print("pip", p.returncode, p.stderr[-1500:], flush=True); assert p.returncode == 0
BUILD = r"""
import glob, io, json, os, sys, time
import numpy as np, torch, tensorrt as trt
p = glob.glob("/kaggle/input/**/e4all_global_fp16.pt", recursive=True)[0]
W = torch.load(p, map_location="cpu", weights_only=True)
L = trt.Logger(trt.Logger.WARNING); b = trt.Builder(L); net = b.create_network(1 << int(trt.NetworkDefinitionCreationFlag.STRONGLY_TYPED)); keep = []
def conv(t, k, s, pad):
    w, bb = (np.ascontiguousarray(W[k + e].contiguous().numpy()) for e in (".w", ".b")); keep.extend([w, bb])
    l = net.add_convolution_nd(t, w.shape[0], (w.shape[2], w.shape[3]), trt.Weights(w), trt.Weights(bb))
    l.stride_nd, l.padding_nd = (s, s), (pad, pad); return l.get_output(0)
relu = lambda t: net.add_activation(t, trt.ActivationType.RELU).get_output(0)
x = net.add_input("x", trt.float16, (94, 3, 320, 320))
h = relu(conv(x, "stem", 2, 3)); mp = net.add_pooling_nd(h, trt.PoolingType.MAX, (3, 3)); mp.stride_nd, mp.padding_nd = (2, 2), (1, 1)
x = mp.get_output(0)
for li, nb in enumerate((3, 4, 6, 3), 1):
    for bi in range(nb):
        q, s = f"layer{li}.{bi}", (2 if li > 1 and bi == 0 else 1)
        h = relu(conv(x, q + ".c1", 1, 0)); h = relu(conv(h, q + ".c2", s, 1)); h = conv(h, q + ".c3", 1, 0)
        sc = conv(x, q + ".ds", s, 0) if bi == 0 else x
        x = relu(net.add_elementwise(h, sc, trt.ElementWiseOperation.SUM).get_output(0))
x.name = "f"; net.mark_output(x)   # strongly typed: fp16 input + fp16 weights -> fp16 throughout
c = b.create_builder_config(); c.set_memory_pool_limit(trt.MemoryPoolType.WORKSPACE, 4 << 30)
c.builder_optimization_level = 4
if len(sys.argv) > 2 and sys.argv[2] == "vc":   # lean runtime: version-compatible plan, lean runtime shipped apart
    c.set_flag(trt.BuilderFlag.VERSION_COMPATIBLE); c.set_flag(trt.BuilderFlag.EXCLUDE_LEAN_RUNTIME)
t = time.perf_counter(); ser = b.build_serialized_network(net, c); bt = time.perf_counter() - t
open(sys.argv[1], "wb").write(bytes(ser))
print(json.dumps({"trt": trt.__version__, "build_s": round(bt, 1), "engine_MB": round(len(bytes(ser)) / 1e6, 1),
                  "dtypes": sorted({str(v.dtype) for v in W.values()})}))
"""
open("/kaggle/working/build.py", "w").write(BUILD)
for tag, mode in (("full", "full"), ("vc", "vc")):
    p = subprocess.run([sys.executable, "/kaggle/working/build.py", f"{P}/r50_e4all_{tag}.engine", mode], capture_output=True, text=True)
    print(tag, p.returncode, p.stdout[-800:], p.stderr[-2000:], flush=True); assert p.returncode == 0
    M[f"build_{tag}"] = json.loads(p.stdout.strip().splitlines()[-1])
import site
sp = [d for d in site.getsitepackages() if os.path.isdir(os.path.join(d, "tensorrt_libs"))][0]
def cp(pkg, dst, only=None):
    src = os.path.join(sp, pkg); os.makedirs(os.path.join(P, dst, pkg), exist_ok=True)
    for f in os.listdir(src):
        if f == "__pycache__" or (only and f not in only):
            continue
        s = os.path.join(src, f); d = os.path.join(P, dst, pkg, f)
        (shutil.copytree if os.path.isdir(s) else shutil.copy2)(s, d)
cp("tensorrt", "full"); cp("tensorrt_bindings", "full"); cp("tensorrt_libs", "full", {"__init__.py", "libnvinfer.so.11"})
cp("tensorrt_lean", "lean"); cp("tensorrt_lean_bindings", "lean"); cp("tensorrt_lean_libs", "lean")
def sha(f):
    h = hashlib.sha256()
    with open(f, "rb") as fh:
        for b in iter(lambda: fh.read(1 << 20), b""): h.update(b)
    return h.hexdigest()
M["files"] = {os.path.relpath(f, P): [os.path.getsize(f), sha(f)] for f in sorted(glob.glob(f"{P}/**/*", recursive=True)) if os.path.isfile(f)}
import torch
M["gpu"] = torch.cuda.get_device_name(0); M["python"] = sys.version.split()[0]; M["torch"] = torch.__version__
M["total_MB"] = round(sum(v[0] for v in M["files"].values()) / 1e6, 1)
json.dump(M, open(f"{P}/manifest.json", "w"), indent=1)
print("PACK", json.dumps({k: v for k, v in M.items() if k != "files"}), flush=True)
